// PlanetChestaBalaOptions supplies optional arguments; nil fields use the server defaults.
type PlanetChestaBalaOptions struct {
	// UseSpecialSunMoon: server default false.
	UseSpecialSunMoon *bool
}

// PlanetChestaBala Calculates Chesta Bala the motional strength of a planet. The method supports three different calculation paths Sun and Moon Normally return zero. When useSpecialSunMoon is true special IshtaKashta formulas are used. Rahu and Ketu Return zero in this implementation. Mars Mercury Jupiter Venus and Saturn Use the mean longitude true longitude and Seeghrochcha aphelionstyle value. The resulting Chesta Kendra is folded into a 0180 range. The final Chesta Bala is calculated by dividing by 3.
// planetName: The planet whose Chesta Bala should be calculated.
// time: The chart time.
// Results are decoded JSON values, or SVG strings for chart endpoints.
func (c *Client) PlanetChestaBala(ctx context.Context, planetName PlanetName, time Time, options ...PlanetChestaBalaOptions) (any, error) {
	if len(options) > 1 {
		return nil, fmt.Errorf("vedastro: PlanetChestaBala accepts at most one options value")
	}
	params := map[string]any{
		"planetName": planetName,
		"time":       time,
	}
	if len(options) == 1 {
		if options[0].UseSpecialSunMoon != nil {
			params["useSpecialSunMoon"] = *options[0].UseSpecialSunMoon
		}
	}
	return c.call(ctx, "PlanetChestaBala", params)
}

